CREATE TABLE map_entity_overlays (map_id bigint NOT NULL REFERENCES maps(id) ON DELETE CASCADE, entity_id bigint NOT NULL REFERENCES entities(id) ON DELETE CASCADE, visible boolean NOT NULL DEFAULT true, pinned boolean NOT NULL DEFAULT false, presentation jsonb NOT NULL DEFAULT '{}', created_by_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(map_id,entity_id), CHECK(jsonb_typeof(presentation)='object'));
CREATE TABLE map_annotations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, map_id bigint NOT NULL, entity_id bigint NOT NULL, author_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(map_id,entity_id) REFERENCES map_entity_overlays(map_id,entity_id) ON DELETE CASCADE, CHECK(body<>''));
CREATE TABLE map_favorites (map_id bigint NOT NULL, entity_id bigint NOT NULL, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(map_id,entity_id,user_id), FOREIGN KEY(map_id,entity_id) REFERENCES map_entity_overlays(map_id,entity_id) ON DELETE CASCADE);
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL, map_id bigint REFERENCES maps(id) ON DELETE SET NULL, action text NOT NULL, target_type text NOT NULL, target_id text, occurred_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}', CHECK(action<>'' AND target_type<>''), CHECK(jsonb_typeof(details)='object'));
CREATE INDEX map_entity_overlays_entity_id_idx ON map_entity_overlays(entity_id); CREATE INDEX audit_events_map_occurred_at_idx ON audit_events(map_id,occurred_at DESC); CREATE INDEX audit_events_actor_occurred_at_idx ON audit_events(actor_user_id,occurred_at DESC);
